CREATE TABLE public.plm_organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, environment text NOT NULL DEFAULT 'SANDBOX', created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT plm_environment CHECK (environment IN ('SANDBOX','PRODUCTION')));
GRANT SELECT ON public.plm_organizations TO authenticated; GRANT ALL ON public.plm_organizations TO service_role;
ALTER TABLE public.plm_organizations ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.plm_memberships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.plm_organizations(id), user_id uuid NOT NULL, site_ids uuid[] NOT NULL DEFAULT '{}', active boolean NOT NULL DEFAULT true, UNIQUE(organization_id,user_id));
GRANT SELECT ON public.plm_memberships TO authenticated; GRANT ALL ON public.plm_memberships TO service_role;
ALTER TABLE public.plm_memberships ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.plm_sites (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.plm_organizations(id), code text NOT NULL, name text NOT NULL, UNIQUE(organization_id,code));
GRANT SELECT ON public.plm_sites TO authenticated; GRANT ALL ON public.plm_sites TO service_role;
ALTER TABLE public.plm_sites ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.plm_has_scope(_org uuid, _site uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.plm_memberships m WHERE m.organization_id=_org AND m.user_id=auth.uid() AND m.active AND (_site IS NULL OR _site=ANY(m.site_ids))); $$;
REVOKE ALL ON FUNCTION public.plm_has_scope(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.plm_has_scope(uuid,uuid) TO authenticated,service_role;
CREATE POLICY plm_org_read ON public.plm_organizations FOR SELECT TO authenticated USING(public.plm_has_scope(id));
CREATE POLICY plm_membership_read ON public.plm_memberships FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY plm_site_read ON public.plm_sites FOR SELECT TO authenticated USING(public.plm_has_scope(organization_id,id));
CREATE TABLE public.plm_entities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.plm_organizations(id), site_id uuid REFERENCES public.plm_sites(id), kind text NOT NULL, code text NOT NULL, normalized_code text GENERATED ALWAYS AS (upper(btrim(code))) STORED, name text NOT NULL, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT plm_kind CHECK(kind IN ('ITEM','BOM','ROUTING','DOCUMENT','CHANGE','PACKAGE','WORK_CENTER')), UNIQUE(organization_id,kind,normalized_code));
GRANT SELECT ON public.plm_entities TO authenticated; GRANT ALL ON public.plm_entities TO service_role;
ALTER TABLE public.plm_entities ENABLE ROW LEVEL SECURITY;
CREATE POLICY plm_entity_read ON public.plm_entities FOR SELECT TO authenticated USING(public.plm_has_scope(organization_id,site_id));
CREATE TABLE public.plm_revisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_id uuid NOT NULL REFERENCES public.plm_entities(id), organization_id uuid NOT NULL REFERENCES public.plm_organizations(id), site_id uuid REFERENCES public.plm_sites(id), revision_label text NOT NULL, parent_revision_id uuid REFERENCES public.plm_revisions(id), item_revision_id uuid REFERENCES public.plm_revisions(id), state text NOT NULL DEFAULT 'DRAFT', version integer NOT NULL DEFAULT 1, payload jsonb NOT NULL DEFAULT '{}', content_hash text NOT NULL, author_id uuid NOT NULL, effective_from date, effective_to date, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT plm_revision_state CHECK(state IN ('DRAFT','IN_REVIEW','APPROVED','RELEASED','SUPERSEDED','WITHDRAWN')), UNIQUE(entity_id,revision_label));
GRANT SELECT ON public.plm_revisions TO authenticated; GRANT ALL ON public.plm_revisions TO service_role;
ALTER TABLE public.plm_revisions ENABLE ROW LEVEL SECURITY;
CREATE POLICY plm_revision_read ON public.plm_revisions FOR SELECT TO authenticated USING(public.plm_has_scope(organization_id,site_id));
CREATE TABLE public.plm_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), revision_id uuid NOT NULL REFERENCES public.plm_revisions(id), organization_id uuid NOT NULL, site_id uuid, candidate_hash text NOT NULL, requested_by uuid NOT NULL, requested_at timestamptz NOT NULL DEFAULT now(), invalidated_at timestamptz);
GRANT SELECT ON public.plm_reviews TO authenticated; GRANT ALL ON public.plm_reviews TO service_role;
ALTER TABLE public.plm_reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY plm_review_read ON public.plm_reviews FOR SELECT TO authenticated USING(public.plm_has_scope(organization_id,site_id));
CREATE TABLE public.plm_decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), review_id uuid NOT NULL REFERENCES public.plm_reviews(id), revision_id uuid NOT NULL REFERENCES public.plm_revisions(id), organization_id uuid NOT NULL, site_id uuid, reviewer_id uuid NOT NULL, candidate_hash text NOT NULL, decision text NOT NULL, meaning text NOT NULL, reason text NOT NULL, reauthenticated_at timestamptz NOT NULL, decided_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT plm_decision CHECK(decision IN ('APPROVED','REJECTED')));
GRANT SELECT ON public.plm_decisions TO authenticated; GRANT ALL ON public.plm_decisions TO service_role;
ALTER TABLE public.plm_decisions ENABLE ROW LEVEL SECURITY;
CREATE POLICY plm_decision_read ON public.plm_decisions FOR SELECT TO authenticated USING(public.plm_has_scope(organization_id,site_id));
CREATE TABLE public.plm_audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, site_id uuid, actor_id uuid NOT NULL, action text NOT NULL, revision_id uuid, reason text NOT NULL, before_value jsonb, after_value jsonb, content_hash text, correlation_id uuid NOT NULL DEFAULT gen_random_uuid(), occurred_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.plm_audit_events TO authenticated; GRANT ALL ON public.plm_audit_events TO service_role;
ALTER TABLE public.plm_audit_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY plm_audit_read ON public.plm_audit_events FOR SELECT TO authenticated USING(public.plm_has_scope(organization_id,site_id));
CREATE TABLE public.plm_action_authorizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, site_id uuid, user_id uuid NOT NULL, revision_id uuid NOT NULL, candidate_hash text NOT NULL, action text NOT NULL, verified_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, used_at timestamptz);
GRANT ALL ON public.plm_action_authorizations TO service_role;
ALTER TABLE public.plm_action_authorizations ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.plm_outbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, site_id uuid, revision_id uuid NOT NULL REFERENCES public.plm_revisions(id), event_type text NOT NULL, schema_version text NOT NULL DEFAULT '1.0', source_module text NOT NULL DEFAULT 'PLMS', content_hash text NOT NULL, envelope jsonb NOT NULL, correlation_id uuid NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.plm_outbox TO authenticated; GRANT ALL ON public.plm_outbox TO service_role;
ALTER TABLE public.plm_outbox ENABLE ROW LEVEL SECURITY;
CREATE POLICY plm_outbox_read ON public.plm_outbox FOR SELECT TO authenticated USING(public.plm_has_scope(organization_id,site_id));
CREATE TABLE public.plm_delivery_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES public.plm_outbox(id), organization_id uuid NOT NULL, site_id uuid, consumer text NOT NULL, status text NOT NULL DEFAULT 'PENDING', detail text, attempted_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT plm_delivery_state CHECK(status IN ('PENDING','TECHNICAL_RECEIPT','FAILED','TIMED_OUT')));
GRANT SELECT ON public.plm_delivery_attempts TO authenticated; GRANT ALL ON public.plm_delivery_attempts TO service_role;
ALTER TABLE public.plm_delivery_attempts ENABLE ROW LEVEL SECURITY;
CREATE POLICY plm_delivery_read ON public.plm_delivery_attempts FOR SELECT TO authenticated USING(public.plm_has_scope(organization_id,site_id));
CREATE TABLE public.plm_inbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, site_id uuid, event_id uuid NOT NULL, consumer text NOT NULL, revision_id uuid NOT NULL, content_hash text NOT NULL, status text NOT NULL, reason text NOT NULL, source_timestamp timestamptz NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT plm_inbox_state CHECK(status IN ('BUSINESS_ACCEPTED','REJECTED','QUARANTINED')), UNIQUE(event_id,consumer));
GRANT SELECT ON public.plm_inbox TO authenticated; GRANT ALL ON public.plm_inbox TO service_role;
ALTER TABLE public.plm_inbox ENABLE ROW LEVEL SECURITY;
CREATE POLICY plm_inbox_read ON public.plm_inbox FOR SELECT TO authenticated USING(public.plm_has_scope(organization_id,site_id));
CREATE TABLE public.plm_inbound_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, site_id uuid, event_id uuid NOT NULL, consumer text NOT NULL, content_hash text NOT NULL, outcome text NOT NULL, reason text NOT NULL, received_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.plm_inbound_attempts TO authenticated; GRANT ALL ON public.plm_inbound_attempts TO service_role;
ALTER TABLE public.plm_inbound_attempts ENABLE ROW LEVEL SECURITY;
CREATE POLICY plm_inbound_attempt_read ON public.plm_inbound_attempts FOR SELECT TO authenticated USING(public.plm_has_scope(organization_id,site_id));
CREATE TABLE public.plm_document_files (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), revision_id uuid NOT NULL UNIQUE REFERENCES public.plm_revisions(id), organization_id uuid NOT NULL, site_id uuid, storage_path text NOT NULL UNIQUE, original_name text NOT NULL, mime_type text NOT NULL, size_bytes bigint NOT NULL, sha256 text NOT NULL, uploaded_by uuid NOT NULL, retained boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.plm_document_files TO authenticated; GRANT ALL ON public.plm_document_files TO service_role;
ALTER TABLE public.plm_document_files ENABLE ROW LEVEL SECURITY;
CREATE POLICY plm_file_read ON public.plm_document_files FOR SELECT TO authenticated USING(public.plm_has_scope(organization_id,site_id));
CREATE TABLE public.plm_document_locks (entity_id uuid PRIMARY KEY REFERENCES public.plm_entities(id), organization_id uuid NOT NULL, site_id uuid, owner_id uuid NOT NULL, acquired_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.plm_document_locks TO authenticated; GRANT ALL ON public.plm_document_locks TO service_role;
ALTER TABLE public.plm_document_locks ENABLE ROW LEVEL SECURITY;
CREATE POLICY plm_lock_read ON public.plm_document_locks FOR SELECT TO authenticated USING(public.plm_has_scope(organization_id,site_id));
CREATE TABLE public.plm_external_references (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, site_id uuid, revision_id uuid NOT NULL REFERENCES public.plm_revisions(id), source_system text NOT NULL, source_object_id text NOT NULL, source_revision_id text NOT NULL, content_hash text NOT NULL, status text NOT NULL DEFAULT 'UNKNOWN', operation_id text, resource_revision_id text, source_updated_at timestamptz NOT NULL, verified_at timestamptz, deep_link text, evidence jsonb NOT NULL DEFAULT '{}');
GRANT SELECT ON public.plm_external_references TO authenticated; GRANT ALL ON public.plm_external_references TO service_role;
ALTER TABLE public.plm_external_references ENABLE ROW LEVEL SECURITY;
CREATE POLICY plm_external_read ON public.plm_external_references FOR SELECT TO authenticated USING(public.plm_has_scope(organization_id,site_id));
CREATE TABLE public.plm_applicability_decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, site_id uuid, revision_id uuid NOT NULL REFERENCES public.plm_revisions(id), requirement text NOT NULL, reason text NOT NULL, authorized_by uuid NOT NULL, valid_from timestamptz NOT NULL, valid_to timestamptz NOT NULL, candidate_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.plm_applicability_decisions TO authenticated; GRANT ALL ON public.plm_applicability_decisions TO service_role;
ALTER TABLE public.plm_applicability_decisions ENABLE ROW LEVEL SECURITY;
CREATE POLICY plm_applicability_read ON public.plm_applicability_decisions FOR SELECT TO authenticated USING(public.plm_has_scope(organization_id,site_id));
CREATE TABLE public.plm_unit_conversions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, item_entity_id uuid REFERENCES public.plm_entities(id), from_unit text NOT NULL, to_unit text NOT NULL, factor numeric(24,9) NOT NULL, basis text NOT NULL, approved_by uuid NOT NULL, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT plm_positive_conversion CHECK(factor>0));
GRANT SELECT ON public.plm_unit_conversions TO authenticated; GRANT ALL ON public.plm_unit_conversions TO service_role;
ALTER TABLE public.plm_unit_conversions ENABLE ROW LEVEL SECURITY;
CREATE POLICY plm_conversion_read ON public.plm_unit_conversions FOR SELECT TO authenticated USING(public.plm_has_scope(organization_id));
CREATE FUNCTION public.plm_retain_evidence() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Controlled evidence is append-only and retained'; END $$;
CREATE TRIGGER plm_audit_retention BEFORE UPDATE OR DELETE ON public.plm_audit_events FOR EACH ROW EXECUTE FUNCTION public.plm_retain_evidence();
CREATE TRIGGER plm_decision_retention BEFORE UPDATE OR DELETE ON public.plm_decisions FOR EACH ROW EXECUTE FUNCTION public.plm_retain_evidence();
CREATE TRIGGER plm_outbox_retention BEFORE UPDATE OR DELETE ON public.plm_outbox FOR EACH ROW EXECUTE FUNCTION public.plm_retain_evidence();
CREATE TRIGGER plm_file_retention BEFORE UPDATE OR DELETE ON public.plm_document_files FOR EACH ROW EXECUTE FUNCTION public.plm_retain_evidence();
CREATE FUNCTION public.plm_sandbox_workspace(_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE oid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF length(btrim(_name)) NOT BETWEEN 2 AND 120 THEN RAISE EXCEPTION 'Workspace name must be 2 to 120 characters'; END IF; IF (SELECT count(*) FROM public.plm_organizations WHERE created_by=auth.uid())>=10 THEN RAISE EXCEPTION 'Workspace limit reached'; END IF; INSERT INTO public.plm_organizations(name,created_by) VALUES(btrim(_name),auth.uid()) RETURNING id INTO oid; INSERT INTO public.plm_memberships(organization_id,user_id) VALUES(oid,auth.uid()); RETURN oid; END $$;
REVOKE ALL ON FUNCTION public.plm_sandbox_workspace(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.plm_sandbox_workspace(text) TO authenticated;
COMMENT ON TABLE public.items IS 'Legacy PLM catalog preserved as unverified reference data; controlled definitions use plm_entities and plm_revisions.';
COMMENT ON COLUMN public.work_centers.capacity_hrs IS 'Reference only: physical capacity authority belongs to EMS/APS.';
COMMENT ON TABLE public.syncs IS 'Legacy simulated delivery records; not authoritative consumer acceptance evidence.';